import{_ as l,a0 as a,w as u,s as r,I as i,x as s,a1 as e,A as n,ao as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"如何在 Ubuntu Linux 上釋放 /boot 分區的空間？ | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu Linux 上釋放 /boot 分區的空間？ | LCTT (202011) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu Linux 上釋放 /boot 分區的空間？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu Linux 上釋放 /boot 分區的空間？ | LCTT (202011) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202011/20201002 How to Free Up Space in -boot Partition on Ubuntu Linux","title":"如何在 Ubuntu Linux 上釋放 /boot 分區的空間？","tag":"202011","desc":""},"relativePath":"202011/20201002 How to Free Up Space in -boot Partition on Ubuntu Linux.md","filePath":"[post].md"}'),d={name:"202011/20201002 How to Free Up Space in -boot Partition on Ubuntu Linux.md"};function b(g,t,m,k,f,h){const o=a("Link");return u(),r("div",null,[t[38]||(t[38]=i("h1",{id:"如何在-ubuntu-linux-上釋放-boot-分區的空間",tabindex:"-1"},[s("如何在 Ubuntu Linux 上釋放 /boot 分區的空間？ "),i("a",{class:"header-anchor",href:"#如何在-ubuntu-linux-上釋放-boot-分區的空間","aria-label":"Permalink to “如何在 Ubuntu Linux 上釋放 /boot 分區的空間？”"},"​")],-1)),t[39]||(t[39]=i("p",null,[s("前幾天，我收到一個警告，"),i("code",null,"/boot"),s(" 分區已經幾乎滿了，沒有剩餘空間了。是的，我有一個獨立的 "),i("code",null,"/boot"),s(" 分區，我相信現在很少有人這樣做了。（LCTT 譯註：個人認為保留單獨的 /boot 分區是個好的運維經驗，除此以外，/tmp、/var 也單獨劃定分區比較好。）")],-1)),i("p",null,[t[1]||(t[1]=s("這是我第一次看到這樣一個錯誤，它讓我很迷惑。現在，這裏有一些 ",-1)),e(o,{href:"https://itsfoss.com/free-up-space-ubuntu-linux/"},{default:n(()=>[...t[0]||(t[0]=[s("方法來釋放在 Ubuntu （或基於 Ubuntu 的分區）上的分區",-1)])]),_:1}),t[2]||(t[2]=s(" ，但是在這種情況下並不是所有的方法都能用。",-1))]),t[40]||(t[40]=p('<p>這就是為什麼我決定寫這些我釋放 <code>/boot</code> 分區空間的步驟的原因。</p><h3 id="如何在-ubuntu-上釋放-boot-分區的空間" tabindex="-1">如何在 Ubuntu 上釋放 /boot 分區的空間 <a class="header-anchor" href="#如何在-ubuntu-上釋放-boot-分區的空間" aria-label="Permalink to “如何在 Ubuntu 上釋放 /boot 分區的空間”">​</a></h3><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2020/10/free-boot-space-ubuntu-linux.jpg?resize=800%2C450&amp;ssl=1" alt=""></p><p>我建議你仔細閲讀這些解決方案，並由此得出最適合你情況的解決方案。解決方案的操作很容易，但是你需要在你的生產力系統上小心的執行這些解決方案。</p><h4 id="方法-1-使用-apt-autoremove" tabindex="-1">方法 1: 使用 apt autoremove <a class="header-anchor" href="#方法-1-使用-apt-autoremove" aria-label="Permalink to “方法 1: 使用 apt autoremove”">​</a></h4><p>你不必是一名終端專家來做這件事，它只需要一個命令，你將移除未使用的內核來釋放 <code>/boot</code> 分區中是空間。</p><p>你所有要做的事情是，輸入:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt autoremove</span></span></code></pre></div><p>這個命令不僅僅可以移除未使用的內核，而且也將移除你不需要的或工具安裝後所不需要的依賴項。</p><p>在你輸入命令後，它將列出將被移除的東西，你只需要確認操作即可。如果你很好奇它將移除什麼，你可以仔細檢查一下看看它實際移除了什麼。</p><p>這裏是它應該看起來的樣子:</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2020/09/apt-autoremove-screenshot.jpg?resize=800%2C415&amp;ssl=1" alt=""></p><p>你必須按 <code>Y</code> 按鍵來繼續。</p><p><strong>值得注意的是，這種方法只在你還剩餘一點點空間，並且得到警告的情況下才有效。但是，如果你的 <code>/boot</code> 分區已經滿了，APT 甚至可能不會工作。</strong></p><p>在接下來的方法中，我將重點介紹兩種不同的方法，通過這些方法你可以使用 GUI 和終端來移除舊內核來釋放空間。</p><h4 id="方法-2-手動移除未使用的內核" tabindex="-1">方法 2: 手動移除未使用的內核 <a class="header-anchor" href="#方法-2-手動移除未使用的內核" aria-label="Permalink to “方法 2: 手動移除未使用的內核”">​</a></h4>',16)),i("p",null,[t[4]||(t[4]=s("在你嘗試 ",-1)),e(o,{href:"https://itsfoss.com/remove-old-kernels-ubuntu/"},{default:n(()=>[...t[3]||(t[3]=[s("移除一些舊內核",-1)])]),_:1}),t[5]||(t[5]=s(" 來釋放空間前，你需要識別當前活動的內核，並且確保你不會刪除它。",-1))]),i("p",null,[t[7]||(t[7]=s("為 ",-1)),e(o,{href:"https://itsfoss.com/find-which-kernel-version-is-running-in-ubuntu/"},{default:n(()=>[...t[6]||(t[6]=[s("檢查你的內核的版本",-1)])]),_:1}),t[8]||(t[8]=s(" ，在終端中輸入下面的命令:",-1))]),t[41]||(t[41]=p('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>uname -r</span></span></code></pre></div>',1)),i("p",null,[e(o,{href:"https://linuxhandbook.com/uname/"},{default:n(()=>[...t[9]||(t[9]=[s("uname 命令通常用於獲取 Linux 系統信息",-1)])]),_:1}),t[10]||(t[10]=s("。在這裏，這個命令顯示當前正在被使用的 Linux 內核。它看起來應該是這樣:",-1))]),t[42]||(t[42]=i("p",null,[i("img",{src:"https://i2.wp.com/itsfoss.com/wp-content/uploads/2020/09/uname-r-screenshot.jpg?resize=800%2C198&ssl=1",alt:""})],-1)),t[43]||(t[43]=i("p",null,"現在，你已經知道你當前的 Linux 內核是什麼，你必須移除一個不同於這個版本的內核。你應該把它記錄在某些地方，以便你不會不知不覺地移除它。",-1)),t[44]||(t[44]=i("p",null,"接下來，要移除它，你可以使用終端或 GUI。",-1)),t[45]||(t[45]=i("blockquote",null,[i("p",null,"警告!"),i("p",null,"在刪除內核時一定要額外的小心。只識別和刪除舊內核，而不是當前你正在使用的內核，否則你將會擁有一個殘缺的系統。")],-1)),t[46]||(t[46]=i("h5",{id:"使用一個-gui-工具來移除舊的-linux-內核",tabindex:"-1"},[s("使用一個 GUI 工具來移除舊的 Linux 內核 "),i("a",{class:"header-anchor",href:"#使用一個-gui-工具來移除舊的-linux-內核","aria-label":"Permalink to “使用一個 GUI 工具來移除舊的 Linux 內核”"},"​")],-1)),i("p",null,[t[14]||(t[14]=s("你可以使用 ",-1)),e(o,{href:"https://itsfoss.com/synaptic-package-manager/"},{default:n(()=>[...t[11]||(t[11]=[s("Synaptic 軟件包管理器",-1)])]),_:1}),t[15]||(t[15]=s(" 或一個類似 ",-1)),e(o,{href:"https://itsfoss.com/optimize-ubuntu-stacer/"},{default:n(()=>[...t[12]||(t[12]=[s("Stacer",-1)])]),_:1}),t[16]||(t[16]=s(" 的工具來開始。就我個人而言，當我遇到一個滿滿的 ",-1)),t[17]||(t[17]=i("code",null,"/boot",-1)),t[18]||(t[18]=s(" 分區且 APT 損壞時，我使用 ",-1)),e(o,{href:"https://linuxhandbook.com/uname/"},{default:n(()=>[...t[13]||(t[13]=[s("Stacer",-1)])]),_:1}),t[19]||(t[19]=s(" 來丟棄舊內核。因此，讓我向你展示一下它看起的樣子。",-1))]),t[47]||(t[47]=p('<p>首先，你需要啓動 Stacer ，然後導航到軟件包卸載器，如下面屏幕截圖所示。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2020/09/stacer-remove-kernel.jpg?resize=800%2C562&amp;ssl=1" alt=""></p><p>在這裏，搜索 “image” ，你將找到你所擁有的 Linux 內核。你只需要刪除舊內核版本的鏡像，而不是當前內核的鏡像。</p><p>在上面的屏幕截圖中，我已經指出了我係統上的當前內核和舊內核，因此你必須注意你係統上的內核。</p><p>你沒有必要刪除任何其它東西，只需要刪除舊的內核版本。</p><p>同樣的，只需要在軟件包列表中搜索 “headers” ，並刪除如下顯示的舊的 “headers” 版本。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2020/09/stacer-remove-kernel-header.png?resize=800%2C576&amp;ssl=1" alt=""></p><p>作為提醒，你 <strong>不會希望移除 <code>linux-headers-generic</code></strong> 。只關注一下那些與其相關的有版本號的就行。</p><p>然後，就這樣，你完成了所有的工作，APT 將會再次工作，並且你將成功地釋放來自 <code>/boot</code> 分區的一些空間。同樣地，你也可以使用任意其它的軟件包管理器來完成這些工作。</p><h4 id="使用命令列來移除舊內核" tabindex="-1">使用命令列來移除舊內核 <a class="header-anchor" href="#使用命令列來移除舊內核" aria-label="Permalink to “使用命令列來移除舊內核”">​</a></h4><p>使用命令列來移除舊內核與使用 GUI 來移除舊內核是一樣的。因此，如果你沒有選擇使用 GUI 軟件（如果它是一台遠程機器/一項遠程服務）的權利，或者如果你只是對終端情有獨鍾，你可以仿效下面的步驟。</p><p>首先，使用下面的命令列出所有已安裝的內核:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ls -l /boot</span></span></code></pre></div><p>它應該看起來像這樣:</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2020/09/command-kernel-list.png?resize=800%2C432&amp;ssl=1" alt=""></p><p>標記為 “old” 的內核，或者不匹配你當前內核版本，都是未使用的內核，你可以刪除它們。</p><p>現在，你可以使用 <code>rm</code> 命令來移除具體指定來自 <code>/boot</code> 分區中的內核，使用下面的命令（一個命令對應一個內核）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo rm /boot/vmlinuz-5.4.0-7634-generic</span></span></code></pre></div><p>務必檢查系統的版本 — 這裏可能與你的系統的版本不同。</p><p>如果你有很多未使用的內核，這將需要一些時間。因此，你也可以下面的命令丟棄多個內核:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo rm /boot/*-5.4.0-{7634}-*</span></span></code></pre></div><p>為了清晰起見，你需要用逗號分隔內核版本號的最後一部分/編碼，以便同時刪除它們。</p><p>假設，我有兩個舊的內核 5.4.0-7634-generic 和 5.4.0-7624 ，那麼命令將是:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo rm /boot/*-5.4.0-{7634,7624}-*</span></span></code></pre></div>',24)),i("p",null,[t[21]||(t[21]=s("如果你不希望在 grub 啓動菜單中再看到這些舊的內核版本，你可以使用下面的命令簡單地 ",-1)),e(o,{href:"https://itsfoss.com/update-grub/"},{default:n(()=>[...t[20]||(t[20]=[s("更新 grub",-1)])]),_:1}),t[22]||(t[22]=s("：",-1))]),t[48]||(t[48]=p(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo update-grub</span></span></code></pre></div><p>就這樣，你完成了所有的工作。你已經釋放了空間，還修復了可能潛在的破損的 APT 問題，如果它是一個在你的 <code>/boot</code> 分區填滿後出現的重要的問題的話。</p><p>在一些情況下，你需要輸入這些命令來修復破損的（正如我在論壇中注意到的）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dpkg --configure -a</span></span>
<span class="line"><span>sudo apt install -f</span></span></code></pre></div><p>注意，除非你發現 APT 已破損，否則你不需要輸入上面的命令。就我個人而言，我不需要這些命令，但是我發現這些命令對論壇上的一些人很有用。</p><hr>`,6)),i("p",null,[t[24]||(t[24]=s("via: ",-1)),e(o,{href:"https://itsfoss.com/free-boot-partition-ubuntu/"},{default:n(()=>[...t[23]||(t[23]=[s("https://itsfoss.com/free-boot-partition-ubuntu/",-1)])]),_:1})]),i("p",null,[t[29]||(t[29]=s("作者：",-1)),e(o,{href:"https://itsfoss.com/author/ankush/"},{default:n(()=>[...t[25]||(t[25]=[s("Ankush Das",-1)])]),_:1}),t[30]||(t[30]=s(" 選題：",-1)),e(o,{href:"https://github.com/lujun9972"},{default:n(()=>[...t[26]||(t[26]=[s("lujun9972",-1)])]),_:1}),t[31]||(t[31]=s(" 譯者：",-1)),e(o,{href:"https://github.com/robsean"},{default:n(()=>[...t[27]||(t[27]=[s("robsean",-1)])]),_:1}),t[32]||(t[32]=s(" 校對：",-1)),e(o,{href:"https://github.com/wxy"},{default:n(()=>[...t[28]||(t[28]=[s("wxy",-1)])]),_:1})]),i("p",null,[t[35]||(t[35]=s("本文由 ",-1)),e(o,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[33]||(t[33]=[s("LCTT",-1)])]),_:1}),t[36]||(t[36]=s(" 原創編譯，",-1)),e(o,{href:"https://linux.cn/"},{default:n(()=>[...t[34]||(t[34]=[s("Linux中國",-1)])]),_:1}),t[37]||(t[37]=s(" 榮譽推出",-1))])])}const v=l(d,[["render",b]]);export{C as __pageData,v as default};
